import { useEffect, useState } from 'react'

// Data of the LärmLupe measurement campaign (generated by pipeline/build_dataset.py in the
// LärmLupe repository). Field documentation: components/Tiles/Climate/Noise/README.md
export type NoiseSlotKey = 'morning' | 'day' | 'evening' | 'night'

export const NOISE_SLOTS: NoiseSlotKey[] = ['morning', 'day', 'evening', 'night']

// Default: static file in public/data. With NEXT_PUBLIC_NOISE_CAMPAIGN_URL the dashboard can
// load the dataset straight from the LärmLupe repository (no redeploy for new measurements).
export const NOISE_CAMPAIGN_URL =
  process.env.NEXT_PUBLIC_NOISE_CAMPAIGN_URL ?? '/data/laerm-kampagne.geojson'

export interface NoiseSlotStats {
  laeq: number | null
  lamax: number | null
  la90: number | null
  minutes: number
  visits: number
  who_ref_db: number
  above_who_ref: boolean
}

export interface NoisePointProperties {
  point_id: string
  name: string
  category: string
  is_static: boolean
  road_type: string
  road_name: string
  maxspeed: string
  tram: boolean
  laeq_all: number | null
  minutes_all: number
  slots: Partial<Record<NoiseSlotKey, NoiseSlotStats>>
}

export interface NoisePointFeature {
  type: 'Feature'
  geometry: { type: 'Point'; coordinates: [number, number] }
  properties: NoisePointProperties
}

export interface NoiseStaticSeries {
  device_id: string
  point_id: string
  hours: { t: string; laeq: number }[]
}

export interface NoiseCampaign {
  type: 'FeatureCollection'
  meta: {
    title: string
    generated_at: string
    period: { from: string | null; to: string | null }
    who_ref_db: { day: number; night: number }
    excluded: Record<string, number>
    static_series: NoiseStaticSeries[]
  }
  features: NoisePointFeature[]
}

export default function useNoiseCampaign(url: string = NOISE_CAMPAIGN_URL) {
  const [data, setData] = useState<NoiseCampaign | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true)
      try {
        const response = await fetch(url)
        if (!response.ok) {
          throw new Error('Failed to fetch')
        }
        setData((await response.json()) as NoiseCampaign)
      } catch {
        setData(null)
      } finally {
        setIsLoading(false)
      }
    }

    fetchData()
  }, [url])

  return { data, isLoading }
}
